import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.D1JEzK2q.js";const m=JSON.parse('{"title":"File Share Bridge API","description":"","frontmatter":{},"headers":[],"relativePath":"api/shares.md","filePath":"api/shares.md"}'),r={name:"api/shares.md"};function s(i,e,n,c,l,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="file-share-bridge-api" tabindex="-1">File Share Bridge API <a class="header-anchor" href="#file-share-bridge-api" aria-label="Permalink to &quot;File Share Bridge API {#file-share-bridge-api}&quot;">​</a></h1><p>Short-lived public file shares + private image artifacts. <code>gateway.publicUrl</code> supplies a convenience URL; a token can also be used with an integration-owned public base. A token IS the capability — only its SHA-256 hash is stored, and shares are unenumerable (there is no list endpoint by design). <strong>The default allowlist is raster images only (PNG / JPEG / WebP);</strong> any other type is rejected with <code>415 unsupported_file_type</code> at both mint and fetch time. A mint may pass <code>allow_documents: true</code> to widen the allowlist to PDF for that request; the allow-kind is then recorded <strong>per share, narrowed to what the ref actually validated as</strong> — a PNG in an <code>allow_documents</code> batch is still stored as image-only — and the file is <strong>re-sniffed on every fetch</strong>, so replacing the file behind a live share never widens what it serves. <code>agent_id</code> and <code>session_id</code> must be valid identifiers (same charset as elsewhere) or the request is <code>400</code> before any path resolution.</p><blockquote><p><strong>Upgrade / rollback note (#444).</strong> The share table was renamed <code>image_shares</code> → <code>file_shares</code>. Upgrading renames in place, so shares minted before the upgrade keep resolving. <strong>Rolling back across #444 does not:</strong> the older build recreates an empty <code>image_shares</code> and every still-live share URL returns <code>404</code> until it expires (bounded by the 24 h max TTL — nothing durable is lost, since shares are ephemeral by design). Rolling forward again folds any rows the older build minted back into <code>file_shares</code> and drops the orphan table, logging <code>[share] migrated legacy image_shares:</code> with the row counts.</p></blockquote><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Auth</th><th>Description</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/v1/shares</code></td><td>Key (agent-scoped)</td><td>Mint one or more shares for artifact refs / media paths → <code>{ items: [{ share_id, token, url?, expires_at, task_id?, provider?, prior_prompt? }] }</code> (order preserved; TTL 10s–24h, default 30 min; idempotent within a 60s window, keyed by allow-kind as well as ref). Optional <code>allow_documents: true</code> widens this request&#39;s allowlist to PDF; anything non-boolean is <code>400</code>. <code>token</code> is a host-agnostic capability and is always present; <code>url</code> is a convenience built from <code>gateway.publicUrl</code> and is omitted when that is unset — callers with their own public base (e.g. LINE) build <code>&lt;base&gt;/shared/&lt;token&gt;</code> themselves. <code>task_id</code>/<code>provider</code>/<code>prior_prompt</code> are echoed <strong>only for artifact refs</strong> (never path refs) and only when the artifact&#39;s generation recorded them — <code>task_id</code>/<code>provider</code> are the provider-side handle a resume-capable backend needs (absent when the generating provider has no resume concept), and <code>prior_prompt</code> is the prompt that produced the artifact; <code>generate_image</code>&#39;s <code>continue_from</code> consumes these to resume or hand off an edit session</td></tr><tr><td><code>DELETE</code></td><td><code>/api/v1/shares/:shareId</code></td><td>Key (owner/admin)</td><td>Revoke a share (uniform <code>404</code> when the key can&#39;t access the owner)</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/image-artifacts</code></td><td>Key (agent-scoped)</td><td>Register generated images as private artifacts (registration never makes a file public)</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/image-catalog?agent_id=&amp;session_id=</code></td><td>Key (agent-scoped)</td><td>Deterministic per-session image list (oldest first); mints nothing, returns no token</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/video-catalog?agent_id=&amp;session_id=</code></td><td>Key (agent-scoped)</td><td>Deterministic per-session video list (oldest first); the video analogue of <code>/v1/image-catalog</code>, kept separate so clips never enter the image-reference surface; mints nothing, returns no token</td></tr><tr><td><code>GET</code>/<code>HEAD</code></td><td><code>/shared/:token</code></td><td>None (token IS the capability)</td><td>Stream the shared file — images <code>inline</code>, documents as an <code>attachment</code> whose filename is sanitised (RFC 8187) and whose <strong>extension is forced to match the sniffed type</strong>, not the agent-chosen basename (so <code>%PDF-</code> bytes named <code>invoice.html</code> download as <code>invoice.pdf</code>); always <code>X-Content-Type-Options: nosniff</code>; uniform <code>404</code> for unknown/expired/revoked/traversal/type-mismatch; per-IP rate limited. This is the single public share primitive — the gateway, MCP subprocesses, and LINE image delivery all mint through <code>/api/v1/shares</code> and serve here</td></tr></tbody></table><p><strong>Renamed in #444</strong> (the bridge is no longer image-only):</p><table tabindex="0"><thead><tr><th>Kind</th><th>Was</th><th>Now</th></tr></thead><tbody><tr><td>Error code</td><td><code>image_ref_not_found</code></td><td><code>share_ref_not_found</code></td></tr><tr><td>Error code</td><td><code>image_too_large</code></td><td><code>file_too_large</code></td></tr><tr><td>Error code</td><td><code>unsupported_image_type</code></td><td><code>unsupported_file_type</code></td></tr><tr><td>MCP tool</td><td><code>share_image</code></td><td><code>share_file</code> (old name kept as a deprecated alias, still image-only — only <code>share_file</code> opts into documents)</td></tr><tr><td>Env vars</td><td><code>IMAGE_SHARE_*</code></td><td><code>SHARE_*</code> (legacy names still read as a fallback)</td></tr><tr><td>SQLite table</td><td><code>image_shares</code></td><td><code>file_shares</code> (renamed in place on first open)</td></tr></tbody></table><p>The error codes are the only breaking part: <code>code</code> values in <code>4xx</code> bodies changed. HTTP statuses, request/response shapes and the token format are unchanged.</p><h2 id="audio-playback-and-fetch-aliases" tabindex="-1">Audio playback and fetch aliases <a class="header-anchor" href="#audio-playback-and-fetch-aliases" aria-label="Permalink to &quot;Audio playback and fetch aliases&quot;">​</a></h2><p>The channel speech pipeline can mint explicitly audio-scoped shares. These serve MP3 as <code>audio/mpeg</code> and M4A as <code>audio/mp4</code>, inline with <code>Accept-Ranges: bytes</code>; a valid single byte range returns <code>206</code> and <code>Content-Range</code>. The ordinary public mint request above remains image/PDF-only: <code>allow_documents</code> does not enable audio.</p><p>All fetch paths below accept <code>GET</code> and <code>HEAD</code>. Other methods return <code>405</code> with <code>Allow: GET, HEAD</code>. Every alias uses the same token lookup, expiry, containment, size and MIME revalidation; an audio suffix must match the actual file type or the request returns <code>404</code>.</p><table tabindex="0"><thead><tr><th>Canonical path</th><th>Direct gateway-prefix alias</th></tr></thead><tbody><tr><td><code>/shared/:token</code></td><td><code>/gateway/shared/:token</code></td></tr><tr><td><code>/shared/:token/audio.m4a</code></td><td><code>/gateway/shared/:token/audio.m4a</code></td></tr><tr><td><code>/shared/:token/audio.mp3</code></td><td><code>/gateway/shared/:token/audio.mp3</code></td></tr></tbody></table>',11)])])}const g=t(r,[["render",s]]);export{m as __pageData,g as default};
